package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Seeds executable procedures only from rules already compiled and source-verified in SupplementContentRegistry. */
public final class CompiledSupplementProcedureBootstrap{
 private CompiledSupplementProcedureBootstrap(){}
 public static synchronized JSONObject install(){int added=0;JSONArray ids=new JSONArray();String[] all={"cozinheiro.pouch.restock","cozinheiro.snack.prepare","cozinheiro.snack.save_dc","cozinheiro.snack.feed","cozinheiro.spice.retry","cozinheiro.accepting_orders","cozinheiro.comfort_meal","cozinheiro.leftovers","animal.training.trick","animal.acclimation","animal.loyalty","animal.care.sustenance","animal.uptime","tasha.patron.assist","tasha.patron.assignment","tasha.sidekick.create","tasha.sidekick.level","tasha.monster.research","tasha.monster.negotiate","tasha.hazard.avalanche","tasha.subclass.change"};for(String id:all){JSONObject c=SupplementContentRegistry.rule(id);if(c.length()==0)continue;JSONObject r=new JSONObject();try{r.put("id",id).put("domain",id.startsWith("animal.")?"animal":(id.startsWith("tasha.")?"tasha_campaign":"cooking")).put("source_book",c.optString("book")).put("source_locator","p."+c.optInt("page")).put("procedure_type",procedure(id)).put("required_inputs",required(id)).put("evidence_hash_basis",c.optString("evidence"));AuthorizedRuleProcedureEngine.register(r);ids.put(id);added++;}catch(Exception ignored){}}JSONObject o=new JSONObject();try{o.put("installed",added).put("rule_ids",ids).put("authority","existing_compiled_supplement_evidence_only");}catch(Exception ignored){}return o;}
 private static String procedure(String id){if(id.equals("cozinheiro.snack.save_dc"))return "formula";if(id.equals("cozinheiro.snack.prepare"))return "rest_generation";if(id.equals("cozinheiro.snack.feed"))return "action_gate";if(id.equals("animal.training.trick"))return "downtime_training";if(id.equals("animal.care.sustenance"))return "daily_sustenance";if(id.equals("animal.acclimation"))return "downtime_acclimation";if(id.equals("animal.uptime"))return "downtime_credit";if(id.equals("cozinheiro.pouch.restock"))return "resource_restock";if(id.equals("cozinheiro.spice.retry"))return "condition_retry";if(id.equals("cozinheiro.accepting_orders"))return "rest_bonus_generation";if(id.equals("cozinheiro.comfort_meal"))return "duration_multiplier";if(id.equals("cozinheiro.leftovers"))return "initiative_recovery";if(id.equals("animal.loyalty"))return "loyalty_delta";if(id.equals("tasha.monster.research"))return "monster_research_check";if(id.equals("tasha.monster.negotiate"))return "monster_social_advantage";if(id.equals("tasha.sidekick.create"))return "sidekick_eligibility";if(id.equals("tasha.sidekick.level"))return "sidekick_level_math";if(id.equals("tasha.subclass.change"))return "subclass_transition_plan";return "state_rule_gate";}
 private static JSONArray required(String id){JSONArray a=new JSONArray();if(id.equals("cozinheiro.snack.save_dc"))return a.put("proficiency_bonus").put("constitution_modifier");if(id.equals("cozinheiro.snack.prepare"))return a.put("constitution_modifier").put("rest_type");if(id.equals("cozinheiro.snack.feed"))return a.put("within_touch").put("free_hand").put("action_available");if(id.equals("animal.training.trick"))return a.put("animal_handling_proficient").put("downtime_days").put("animal_intelligence").put("trainer_wisdom_modifier");if(id.equals("animal.care.sustenance"))return a.put("size");if(id.equals("animal.acclimation"))return a.put("animal_handling_proficient").put("animal_category").put("captive").put("downtime_days");if(id.equals("animal.uptime"))return a.put("long_rest").put("requirements_available");if(id.equals("cozinheiro.pouch.restock"))return a.put("method").put("gold_available").put("hours_available");if(id.equals("cozinheiro.spice.retry"))return a.put("cook_level").put("condition").put("bonus_action_available");if(id.equals("cozinheiro.accepting_orders"))return a.put("cook_level").put("constitution_modifier").put("rest_type");if(id.equals("cozinheiro.comfort_meal"))return a.put("cook_level").put("shared_long_rest");if(id.equals("cozinheiro.leftovers"))return a.put("cook_level").put("initiative_rolled").put("snacks_remaining").put("known_snack_available");if(id.equals("animal.loyalty"))return a.put("current_loyalty").put("handler_wisdom").put("delta_roll").put("direction");if(id.equals("tasha.monster.research"))return a.put("monster_type").put("challenge_rating").put("skill").put("check_total");if(id.equals("tasha.monster.negotiate"))return a.put("monster_type").put("desire_roll").put("offer_matches_desire");if(id.equals("tasha.sidekick.create"))return a.put("statblock_id").put("friendship_established").put("can_speak_language").put("sidekick_class");if(id.equals("tasha.sidekick.level"))return a.put("current_level").put("hp_die_roll").put("constitution_modifier");if(id.equals("tasha.subclass.change"))return a.put("class_level").put("returning_to_previous").put("sudden_approved");return a;}
}
